pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 burnAmount) internal {
        uint256 ownerBalBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { ownerBalBefore = __r; } catch { return; }
        uint256 totalSupplyBefore;
        try c.totalSupply() returns (uint256 __r) { totalSupplyBefore = __r; } catch { return; }
        bool reverted;
        try c.burn(burnAmount) { reverted = false; } catch { reverted = true; }
        uint256 ownerBalAfter;
        try c.balanceOf(address(this)) returns (uint256 __r) { ownerBalAfter = __r; } catch { return; }
        uint256 totalSupplyAfter;
        try c.totalSupply() returns (uint256 __r) { totalSupplyAfter = __r; } catch { return; }
        assertTrue((reverted && burnAmount > ownerBalBefore && ownerBalAfter == ownerBalBefore && totalSupplyAfter == totalSupplyBefore) ||
            (!reverted && burnAmount <= ownerBalBefore && ownerBalAfter == ownerBalBefore - burnAmount && totalSupplyAfter == totalSupplyBefore - burnAmount));
    }

    function testFuzz_run(uint256 burnAmount) public {
        _run(burnAmount);
    }

    receive() external payable {}
}
